-- CREATE TASK parameters taking an identifier, OVERLAP_POLICY and EXECUTE AS USER
-- https://docs.snowflake.com/en/sql-reference/sql/create-task

CREATE TASK t1 WAREHOUSE = wh1 ERROR_INTEGRATION = my_int AS SELECT 1;

CREATE TASK t1 WAREHOUSE = wh1 SUCCESS_INTEGRATION = my_int AS SELECT 1;

CREATE TASK t1
WAREHOUSE = wh1
ERROR_INTEGRATION = my_db.my_schema.err_int
SUCCESS_INTEGRATION = ok_int
AS
SELECT 1;

CREATE TASK tf WAREHOUSE = wh1 FINALIZE = my_root_task AS SELECT 1;

CREATE TASK t1 WAREHOUSE = wh1 OVERLAP_POLICY = ALLOW_ALL_OVERLAP AS SELECT 1;

CREATE TASK t1 WAREHOUSE = wh1 OVERLAP_POLICY = NO_OVERLAP AS SELECT 1;

CREATE TASK t1 WAREHOUSE = wh1 OVERLAP_POLICY = ALLOW_CHILD_OVERLAP AS SELECT 1;

CREATE TASK t1
WAREHOUSE = wh1
SCHEDULE = '5 MINUTES'
EXECUTE AS USER admin_user
AS
SELECT 1;

CREATE TASK t1
WAREHOUSE = wh1
AFTER parent_task
EXECUTE AS USER admin_user
WHEN SYSTEM$STREAM_HAS_DATA('my_stream')
AS
SELECT 1;

CREATE TASK t2
WAREHOUSE = wh1
SCHEDULE = '5 MINUTES'
EXECUTE AS USER admin_user
WHEN SYSTEM$STREAM_HAS_DATA('my_stream')
AS
SELECT 1;

CREATE OR REPLACE TASK t1
WITH TAG (cost_center = 'sales')
WITH CONTACT (STEWARD = data_steward, SUPPORT = support_contact)
WAREHOUSE = wh1
SCHEDULE = '5 MINUTES'
AS
SELECT 1;
